#!/usr/bin/env node
// Post-process the Android project generated by `cap add android` (CI only; android/ is not committed):
// - CAMERA permission for the pid QR scan (BarcodeDetector + getUserMedia in the WebView);
//   the camera is optional so tablets without one can still type the code;
// - no cloud/device-transfer backup of the SQLite research database (android:allowBackup=false,
//   android:fullBackupContent=false).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const manifestPath = fileURLToPath(
  new URL('../android/app/src/main/AndroidManifest.xml', import.meta.url),
);
let xml = readFileSync(manifestPath, 'utf8');

const additions = [
  '<uses-permission android:name="android.permission.CAMERA" />',
  '<uses-feature android:name="android.hardware.camera" android:required="false" />',
];
for (const line of additions) {
  if (!xml.includes(line)) xml = xml.replace('</manifest>', `    ${line}\n</manifest>`);
}

xml = xml.replace(/android:allowBackup="true"/, 'android:allowBackup="false"');
if (!xml.includes('android:allowBackup')) {
  xml = xml.replace('<application', '<application\n        android:allowBackup="false"');
}
if (!xml.includes('android:fullBackupContent')) {
  xml = xml.replace('<application', '<application\n        android:fullBackupContent="false"');
}

writeFileSync(manifestPath, xml);
console.log(`patched ${manifestPath}`);
